import {NextResponse} from "next/server";import {list,save} from "@/lib/store";import {sleepSchema,approvalSchema,deploymentSchema} from "@/lib/validations";import {inngest} from "@/inngest/client";import type {Workflow,WorkflowKind} from "@/lib/types";
export async function GET(){return NextResponse.json(await list())}
export async function POST(req:Request){try{const body=await req.json();const kind=body.kind as WorkflowKind;const data=kind==="sleep"?sleepSchema.parse(body):kind==="approval"?approvalSchema.parse(body):deploymentSchema.parse(body);const id=crypto.randomUUID();const now=new Date().toISOString();const item:Workflow={id,name:kind==="sleep"?data.name:kind==="approval"?data.title:`Deploy ${data.service}`,kind,status:kind==="sleep"?"sleeping":"waiting",createdAt:now,updatedAt:now,deadline:kind==="approval"?new Date(Date.now()+Number(data.deadline)*3600000).toISOString():undefined,meta:data as Record<string,string|number>,steps:kind==="sleep"?[{id:"start",label:"Workflow started",status:"done",time:now},{id:"wait",label:`Sleep for ${data.delay} ${data.unit}`,status:"running"},{id:"finish",label:"Send notification",status:"pending"}]:kind==="approval"?[{id:"request",label:"Approval request created",status:"done",time:now},{id:"wait",label:"Waiting for human approval",status:"running"},{id:"finish",label:"Continue workflow",status:"pending"}]:[{id:"validate",label:"Validate deployment request",status:"done",time:now},{id:"security",label:"Run security check",status:"running"},{id:"approval",label:"Manager approval",status:"pending"},{id:"deploy",label:"Deploy service",status:"pending"},{id:"notify",label:"Send success notification",status:"pending"}]};await save(item);const event=kind==="sleep"?"workflow/sleep.requested":kind==="approval"?"workflow/approval.requested":"workflow/deployment.requested";try{await inngest.send({name:event,data:{...data,workflowId:id,requestId:id}})}catch{}return NextResponse.json(item,{status:201})}catch(e){return NextResponse.json({error:e instanceof Error?e.message:"Invalid request"},{status:400})}}
